/* Continuous in-place disclosure. Existing data, filters and separate windows remain available. */
let fluidOpen=null;
let fluidTransition=null;
let fluidPoint=null;
function fluidPolish(){
  // Search clicks and published count are already prominent in the results area.
  if(!decision.active)panoPage.querySelectorAll('.p-kpi[data-value="organic"],.p-kpi[data-value="content"]').forEach(el=>el.remove());
  panoPage.querySelector('.p-kpis')?.classList.toggle('four-metrics',!decision.active);
  const grid=panoPage.querySelector('.p-grid');if(!grid)return;
  const rehearsal=$('#rehearsalStrip');if(rehearsal)grid.after(rehearsal);
  let commands=panoPage.querySelector('.command-strip');
  if(!commands){commands=document.createElement('div');commands.className='command-strip';commands.innerHTML=`<div><span class="command-symbol">⌘</span><span>当前正在查看<strong id="commandTarget">${panoCards[pano.focus][1]}</strong></span></div><nav aria-label="数据指令">${[['inspect','查看依据'],['compare','比较范围'],['plan','安排跟进'],['tasks','查看行动']].map(([k,l])=>`<button data-command="${k}">${l}<span>↗</span></button>`).join('')}</nav>`;}
  grid.before(commands);commands.querySelector('.precision-range')?.remove();const range=document.createElement('small');range.className='precision-range';range.textContent=pScope();commands.querySelector('#commandTarget').textContent=panoCards[pano.focus][1];commands.querySelector('#commandTarget').after(range);panoPage.style.setProperty('--command-height',(commands.getBoundingClientRect().height+8)+'px');
  const feedback=$('#commandFeedback');if(feedback)commands.after(feedback);
  panoPage.querySelectorAll('.p-card').forEach(card=>{const key=card.dataset.card,footer=card.querySelector('footer');if(footer&&!footer.querySelector('.precision-actions')){const note=footer.querySelector('span');if(note)note.classList.add('precision-note');footer.querySelectorAll('button').forEach(b=>b.remove());const actions=document.createElement('div');actions.className='precision-actions';actions.innerHTML=`<button data-fluid="toggle" data-key="${key}">展开分析</button><button data-pano="discuss" data-value="${key}">讨论</button><button data-precision-plan="${key}">安排跟进</button>`;footer.append(actions);}});
}
const fluidReduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function fluidDecorate(){fluidPolish();panoPage.querySelectorAll('.p-card').forEach(card=>{const key=card.dataset.card,button=card.querySelector('[data-pano="expand"]');if(button){button.setAttribute('aria-expanded',String(fluidOpen?.key===key));button.setAttribute('aria-controls','inline-'+key);button.setAttribute('aria-label',(fluidOpen?.key===key?'收起':'展开')+panoCards[key][1]);button.title='原位展开 / 收起';button.innerHTML=fluidOpen?.key===key?'−':'＋';}const title=card.querySelector('header h2');if(title&&!title.querySelector('button')){const b=document.createElement('button');b.className='fluid-title';b.dataset.fluid='toggle';b.dataset.key=key;b.textContent=title.textContent;title.replaceChildren(b);}card.querySelectorAll('[data-fluid="toggle"]').forEach(b=>{b.setAttribute('aria-expanded',String(fluidOpen?.key===key));if(!b.classList.contains('fluid-title'))b.textContent=fluidOpen?.key===key?'收起分析':'展开分析';});});}
function fluidDetails(card,key){const scope=pSnapshot(),snapshotKey=`inline_${key}_${scope.topic}_${scope.start}_${scope.end}`;panoSnapshots.set(snapshotKey,{...scope,card:key,subset:'',snapshotKey});const content=document.createElement('section');content.id='inline-'+key;content.className='inline-analysis';content.setAttribute('aria-label',panoCards[key][1]+'展开分析');content.innerHTML=`<div class="fluid-toolbar"><span><i></i> ${pScope()} · 与全盘联动</span><div><button data-fluid="discuss" data-key="${key}">解读当前数据</button><button data-fluid="window" data-key="${key}">独立窗口 ↗</button><button data-fluid="close">收起 ↑</button></div></div><div class="fluid-records">${pDetails(key,{...scope,snapshotKey})}</div>`;card.querySelector('.p-body').after(content);}
function fluidApply(key,scroll=true){const card=panoPage.querySelector(`[data-card="${key}"]`);if(!card||card.hidden)return;panoPage.querySelectorAll('.p-card').forEach(el=>el.classList.remove('is-focused'));card.classList.add('expanded','fluid-expanded','is-focused');card.style.viewTransitionName='active-analysis';fluidDetails(card,key);pano.focus=key;pContext();panoPage.classList.add('has-expanded-analysis');fluidDecorate();if(scroll){const page=$('#pageScroll'),r=card.getBoundingClientRect(),pr=page.getBoundingClientRect();page.scrollTop+=r.top-pr.top-(panoPage.querySelector('.command-strip')?.getBoundingClientRect().height||0)-20;card.querySelector('[data-pano="expand"]')?.focus({preventScroll:true});}}
function fluidCollapse(restore=true){if(!fluidOpen)return;const {key,scrollTop}=fluidOpen,card=panoPage.querySelector(`[data-card="${key}"]`);if(card){card.classList.remove('expanded','fluid-expanded');card.querySelector('.inline-analysis')?.remove();card.style.viewTransitionName='active-analysis';}fluidOpen=null;pano.expanded.delete(key);panoPage.classList.remove('has-expanded-analysis');fluidDecorate();if(restore){$('#pageScroll').scrollTop=scrollTop;card?.querySelector('[data-pano="expand"]')?.focus({preventScroll:true});}}
function fluidAnimate(change){if(fluidTransition)fluidTransition.skipTransition();if(!document.startViewTransition||fluidReduced()){change();return;}const transition=document.startViewTransition(change);fluidTransition=transition;transition.finished.catch(()=>{}).finally(()=>{if(fluidTransition===transition)fluidTransition=null;});}
function fluidToggle(key){if(fluidTransition)return;if(fluidOpen?.key===key){fluidAnimate(()=>fluidCollapse());return;}const card=panoPage.querySelector(`[data-card="${key}"]`);if(!card||card.hidden)return;panoPage.querySelectorAll('.p-card').forEach(c=>c.style.viewTransitionName='none');card.style.viewTransitionName='active-analysis';fluidAnimate(()=>{if(fluidOpen){const old=panoPage.querySelector('[data-card="'+fluidOpen.key+'"]');fluidCollapse(false);if(old)old.style.viewTransitionName='none';}fluidOpen={key,scrollTop:$('#pageScroll').scrollTop};fluidApply(key);});}
const fluidBaseRender=renderPanorama;renderPanorama=function(){const retained=fluidOpen;fluidBaseRender();fluidDecorate();if(retained){const card=panoPage.querySelector(`[data-card="${retained.key}"]`);if(card&&!card.hidden){fluidApply(retained.key,false);}else{fluidOpen=null;panoPage.classList.remove('has-expanded-analysis');}}};
window.addEventListener('click',e=>{const expand=e.target.closest('[data-pano="expand"],[data-fluid="toggle"]');if(expand){e.preventDefault();e.stopImmediatePropagation();fluidToggle(expand.dataset.value||expand.dataset.key);return;}const b=e.target.closest('[data-fluid]');if(b){e.preventDefault();e.stopImmediatePropagation();if(b.dataset.fluid==='close')fluidAnimate(()=>fluidCollapse());if(b.dataset.fluid==='window')pOpen(b.dataset.key);if(b.dataset.fluid==='discuss'){pano.focus=b.dataset.key;pTalk(b.dataset.key,`解读当前展开的数据：${pScope()}`);}return;}const circle=e.target.closest('svg[data-p-chart] circle');if(circle){const date=circle.querySelector('title')?.textContent.match(/^\d{2}-\d{2}/)?.[0],day=dates.indexOf(date);if(day>=0){e.preventDefault();e.stopImmediatePropagation();pChange({start:day,end:day});commandFeedback(`已选择 ${date} · 所有图表同步 · 可撤销筛选`);}}},true);
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&fluidOpen&&!$('#detailDialog').open&&!e.target.closest('.detail-window')){e.preventDefault();fluidAnimate(()=>fluidCollapse());}});
window.addEventListener('pointerdown',e=>{const circle=e.target.closest('svg[data-p-chart] circle');const date=circle?.querySelector('title')?.textContent.match(/^\d{2}-\d{2}/)?.[0];fluidPoint=date?{day:dates.indexOf(date),x:e.clientX,y:e.clientY,pointer:e.pointerId}:null;},true);
window.addEventListener('pointerup',e=>{const point=fluidPoint;fluidPoint=null;if(!point||point.day<0||point.pointer!==e.pointerId||Math.hypot(e.clientX-point.x,e.clientY-point.y)>5)return;e.preventDefault();e.stopImmediatePropagation();pChange({start:point.day,end:point.day});commandFeedback(`已选择 ${dates[point.day]} · 所有图表同步 · 可撤销筛选`);},true);
window.addEventListener('pointercancel',()=>fluidPoint=null,true);
window.addEventListener('resize',()=>{const bar=panoPage.querySelector('.command-strip');if(bar)panoPage.style.setProperty('--command-height',(bar.getBoundingClientRect().height+8)+'px');});
window.addEventListener('click',e=>{const b=e.target.closest('[data-precision-plan]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();pano.focus=b.dataset.precisionPlan;pPlan(pano.focus);},true);
// Keep expansion controls named and reachable without changing existing navigation.
fluidDecorate();
